def get_post_traumatic_stress_disorder_therapy_priority(patient):
    """
    Compute the post-traumatic stress disorder (PTSD) therapy priority of the patient.
    patient: A patient object with attributes: resource_availability, gender, symptoms, severity, age, duration_of_condition, comorbidities
    Returns: An integer score representing the therapy priority (higher score = higher priority)
    """
    score = 0

    # Higher severity of PTSD symptoms increases priority
    if patient.severity >= 7:
        score += 3
    elif 4 <= patient.severity < 7:
        score += 2
    else:
        score += 1

    # More severe PTSD symptoms contribute to higher priority
    severe_symptoms = ['flashbacks', 'nightmares', 'hypervigilance', 'emotional_numbing', 'avoidance_behavior']
    symptom_count = sum(1 for symptom in patient.symptoms if symptom in severe_symptoms)
    if symptom_count >= 3:
        score += 3
    elif symptom_count >= 2:
        score += 2
    else:
        score += 1

    # Longer duration of PTSD condition may indicate chronicity
    if patient.duration_of_condition > 24:  # More than 6 months
        score += 3
    elif 12 < patient.duration_of_condition <= 24:  # 3 to 6 months
        score += 2
    elif 4 < patient.duration_of_condition <= 12:  # 1 to 3 months
        score += 1

    # More comorbidities may complicate treatment
    if patient.comorbidities >= 3:
        score -= 1  # Lower priority due to comorbidities
    elif patient.comorbidities >= 1:
        score -= 0.5  # Slightly lower priority

    # Higher resource availability improves access to care
    if patient.resource_availability >= 3:
        score += 2
    elif patient.resource_availability >= 2:
        score += 1

    # Women are more likely to develop PTSD, so higher priority
    if patient.gender == 'female':
        score += 1

    # Middle-aged or older adults may have unique needs
    if 45 <= patient.age <= 65:
        score += 1
    elif patient.age > 65:
        score += 0.5

    return round(score)

